class Solution:
    def toHexspeak(self, num: str) -> str:
        s = format(int(num), 'X')
        res = []
        for c in s:
            if c == '0':
                res.append('O')
            elif c == '1':
                res.append('I')
            elif c.isdigit():
                return "ERROR"
            else:
                res.append(c)
        return ''.join(res)

