class Solution:
    def toHexspeak(self, num: str) -> str:
        n = int(num)
        digits = []
        while n > 0:
            d = n % 16
            digits.append(chr(ord('A') + d - 10) if d >= 10 else chr(ord('0') + d))
            n //= 16
        res = []
        for c in reversed(digits):
            if c == '0': res.append('O')
            elif c == '1': res.append('I')
            elif c.isdigit(): return "ERROR"
            else: res.append(c)
        return ''.join(res)

