var toHexspeak = function(num) {
    let n = Number(num), digits = [];
    while (n > 0) {
        const d = n % 16;
        digits.push(String.fromCharCode(d >= 10 ? 65 + d - 10 : 48 + d));
        n = Math.floor(n / 16);
    }
    let res = '';
    for (let i = digits.length - 1; i >= 0; i--) {
        const c = digits[i];
        if (c === '0') res += 'O';
        else if (c === '1') res += 'I';
        else if (c >= '2' && c <= '9') return "ERROR";
        else res += c;
    }
    return res;
};
